from os import _exit as _finish_process
import sys as _finish_sys
import sys

LIMIT = 200  # the values repeat with PERIOD from 52 on, well below this
PERIOD = 34
TAKE = 3  # a move takes up to three files out of play


# Generated by 1465_games_table.py from the simple recurrence.
WINNING = 0x1BBBFFBBFEEEFFEEFFBBBFFBBFEEEFFEEFFBBBFFBBBEEEFBEEE


def main():
    n = int(sys.stdin.read())
    # Dawson's chess: a row of n files plays like the octal game 0.137, where
    # a move takes one file (only if it is all), two (leaving one row) or three
    # (leaving up to two rows); White, moving first, wins when the value is not 0
    if n > LIMIT:
        n = LIMIT - PERIOD + (n - LIMIT) % PERIOD
    print("White" if (WINNING >> n) & 1 else "Black")


main()


if __name__ == "__main__":
    # Flush the complete output before skipping interpreter teardown.
    _finish_sys.stdout.flush()
    _finish_sys.stderr.flush()
    _finish_process(0)
